/**
 * Machine-actionable guidance every error this SDK raises carries, derived
 * from the contract and from an RFC 9457 problem-details body when the server
 * sends one. Configured credential values never appear in it.
 */
export interface Remediation {
  /** Conservative runtime observation bound to this operation and generated package. */
  recovery?: { schema?: string; generator_version?: string; operation_id?: string; contract_sha256?: string;
    source_version?: string | null; package_name?: string; package_version?: string;
    binding_sha256?: string; effect?: "read_only" | "may_write";
    outcome: "before_effects" | "acknowledged" | "in_doubt"; retry_safe: boolean; action: string };
  /** Stable reason, such as `authentication_failed`, `not_found` or `rate_limited`. */
  code: string;
  cause: string;
  /** What to change or wait for before trying again. */
  action: string;
  retryable: boolean;
  /** Configured response bound when the response was refused as too large. */
  limit?: number;
  /** Where the recovery is documented: the problem type URI or this README. */
  docs: string;
  /** The SDK argument at fault. */
  parameter?: string;
  /** JSON pointer inside that argument. */
  pointer?: string;
  schemes?: string[];
  /** Client options that feed the refused or missing credential. */
  credentialOptions?: string[];
  /** Seconds the server asked the caller to wait. */
  retryAfter?: number;
  fields?: Array<{ field: string; parameter?: string; pointer?: string; message?: string }>;
}

export interface APIErrorShape extends OmniWrapErrorShape {
  status?: number;
  headers: Record<string, string>;
  body?: unknown;
  code?: string;
  operation?: string;
  requestId?: string;
  attempts: number;
  retryable: boolean;
  /** Set on every error the SDK raises; null only for one built by hand. */
  remediation: Remediation | null;
}

export interface APIErrorConstructor {
  new(message: string, details?: Record<string, unknown>): APIErrorShape;
  /** The subclass this HTTP status names, carrying the peer's own message. */
  from(details?: Record<string, unknown>): APIErrorShape;
}

/** Raised only for a caller-supplied AbortSignal; extends APIError. */
export interface APIUserAbortErrorShape extends APIErrorShape {}

export interface APIUserAbortErrorConstructor {
  new(details?: Record<string, unknown>): APIUserAbortErrorShape;
}

export interface ResponseTooLargeErrorShape extends APIErrorShape { limit: number; }
export interface ResponseTooLargeErrorConstructor {
  new(limit: number, operation?: string): ResponseTooLargeErrorShape;
}
export interface NDJSONDecodeErrorShape extends APIErrorShape { lineNumber: number; }
export interface NDJSONDecodeErrorConstructor {
  new(lineNumber: number, operation?: string, cause?: unknown): NDJSONDecodeErrorShape;
}

/**
 * HTTP 401, and the credential gates that refuse a request which could never
 * authenticate: `status === 401` is a request the peer answered, an absent
 * status is a request that was never sent.
 */
export interface AuthenticationErrorShape extends APIErrorShape {}

export interface AuthenticationErrorConstructor {
  new(
    message: string,
    details?: Record<string, unknown> | string,
  ): AuthenticationErrorShape;
}

/** No request was sent: this client holds no credential the contract requires. */
export interface MissingCredentialsErrorShape extends AuthenticationErrorShape {}

export interface MissingCredentialsErrorConstructor {
  new(
    message: string,
    details?: Record<string, unknown> | string,
  ): MissingCredentialsErrorShape;
}

export interface APIConnectionErrorShape extends APIErrorShape {
  cause?: unknown;
}

export interface APIConnectionErrorConstructor {
  new(message: string, details?: Record<string, unknown>): APIConnectionErrorShape;
}

export interface APITimeoutErrorShape extends APIConnectionErrorShape {
  timeout?: number;
}

export interface APITimeoutErrorConstructor {
  new(message: string, details?: Record<string, unknown>): APITimeoutErrorShape;
}

