export interface ClientOptions {
  baseURL?: string;
  apiKey?: string | (() => string | Promise<string>);
  accessToken?: string | (() => string | Promise<string>);
  auth?: Record<string, string | (() => string | Promise<string>)>;
  defaultHeaders?: Record<string, string>;
  timeout?: number;
  maxRetries?: number;
  /** Maximum buffered success or error response size (default 8388608 bytes). */
  maxResponseBytes?: number;
  /** Maximum size of one SSE event or NDJSON line (default 1000000 bytes). */
  maxStreamEventBytes?: number;
  /**
   * Longest wait, in milliseconds, a retry honours (default 60000). When the
   * server asks for more through Retry-After, retry-after-ms or a RateLimit
   * reset, its error is surfaced at once instead of retrying early.
   */
  maxRetryDelay?: number;
  /** Ceiling, in milliseconds, on a whole call including every retry wait. */
  retryBudget?: number;
  /**
   * Ordered alternate base URLs. Only idempotent operations use them, and
   * only after a connection failure or a 5xx response; hook contexts name the
   * endpoint each attempt used.
   */
  fallbackBaseURLs?: string[];
  fetch?: typeof fetch;
  /** Request lifecycle hooks; see `ClientHooks`. */
  hooks?: ClientHooks;
  /** Opens one span per call; see `ClientTracer`. */
  tracer?: ClientTracer;
  sleep?: (milliseconds: number) => Promise<unknown>;
  random?: () => number;
  /**
   * Fetch `credentials` mode forwarded to every request. When set, the user
   * agent owns each cookie security scheme (for example an HttpOnly session
   * cookie): the client never asks for, stores or writes that cookie, and a
   * contract whose every operation requires it can be constructed without a
   * credential.
   */
  credentials?: "omit" | "same-origin" | "include";
  /**
   * Mint an `Idempotency-Key` (UUID) for every POST so it can be retried
   * safely. POSTs the contract marks idempotent always receive one.
   */
  autoIdempotencyKey?: boolean;
  /**
   * The most bytes one multipart part may buffer from a stream, an async
   * iterable or a fetch `Response` (default 104857600, `Infinity` lifts it).
   * Past it the call rejects with a `RangeError` whose `code` is
   * `"UPLOAD_TOO_LARGE"`, before any request is sent.
   */
  maxUploadBytes?: number;
}

